// Workflow layer — generated by line-matcher. Do not add logic that belongs to another layer.
// Application flow and state (XState). Talks to the Service layer only.
import { setup, assign, fromPromise } from "xstate";
import * as service from "../service/products.service.js";

export const productsWorkflow = setup({
  actors: {
    load: fromPromise(() => service.listProducts()),
    create: fromPromise(({ input }) => service.createProduct(input.data)),
    update: fromPromise(({ input }) => service.updateProduct(input.id, input.data)),
    remove: fromPromise(({ input }) => service.deleteProduct(input.id)),
  },
  actions: {
    setError: assign({ error: ({ event }) => String(event.error?.message ?? event.error) }),
  },
  guards: {
    hasSelection: ({ context }) => context.selectedId != null,
  },
}).createMachine({
  id: "products",
  initial: "loading",
  context: { items: [], selectedId: null, error: null },
  states: {
    loading: {
      invoke: {
        src: "load",
        onDone: {
          target: "ready",
          actions: assign({ items: ({ event }) => event.output, error: null }),
        },
        onError: { target: "failed", actions: "setError" },
      },
    },
    ready: {
      on: {
        EDIT: { actions: assign({ selectedId: ({ event }) => event.id, error: null }) },
        DELETE: { target: "removing" },
        SAVE: [{ guard: "hasSelection", target: "updating" }, { target: "creating" }],
        CANCEL: { actions: assign({ selectedId: null }) },
      },
    },
    creating: {
      invoke: {
        src: "create",
        input: ({ event }) => ({ data: event.data }),
        onDone: { target: "loading", actions: assign({ selectedId: null }) },
        onError: { target: "ready", actions: "setError" },
      },
    },
    updating: {
      invoke: {
        src: "update",
        input: ({ context, event }) => ({ id: context.selectedId, data: event.data }),
        onDone: { target: "loading", actions: assign({ selectedId: null }) },
        onError: { target: "ready", actions: "setError" },
      },
    },
    removing: {
      invoke: {
        src: "remove",
        input: ({ event }) => ({ id: event.id }),
        onDone: { target: "loading", actions: assign({ selectedId: null }) },
        onError: { target: "ready", actions: "setError" },
      },
    },
    failed: {
      on: { RETRY: "loading" },
    },
  },
});
